{
  "name": "@stablekernel/opencode-cursor",
  "version": "0.10.2",
  "description": "opencode provider plugin backed by the official Cursor SDK (@cursor/sdk) — adds a Cursor provider and lists its models",
  "type": "module",
  "license": "MIT",
  "author": "justin-carper (https://github.com/justin-carper)",
  "repository": {
    "type": "git",
    "url": "https://github.com/stablekernel/opencode-cursor.git"
  },
  "homepage": "https://github.com/stablekernel/opencode-cursor#readme",
  "bugs": {
    "url": "https://github.com/stablekernel/opencode-cursor/issues"
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cursor",
    "cursor-sdk",
    "ai-sdk",
    "provider"
  ],
  "files": [
    "dist",
    "server.js",
    "README.md",
    "CHANGELOG.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": {
      "types": "./dist/provider/index.d.ts",
      "import": "./dist/provider/index.js"
    },
    "./server": {
      "types": "./dist/plugin/index.d.ts",
      "import": "./dist/plugin/index.js"
    },
    "./plugin": {
      "types": "./dist/plugin/index.d.ts",
      "import": "./dist/plugin/index.js"
    }
  },
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:e2e": "vitest run --config vitest.e2e.config.ts --passWithNoTests",
    "sync:model-limits": "node scripts/sync-model-limits-cli.mjs",
    "prepublishOnly": "npm run typecheck && npm test && npm run build"
  },
  "dependencies": {
    "@connectrpc/connect-node": "^2.3.0",
    "@cursor/sdk": "^1.1.0",
    "@opencode-ai/plugin": "^1.19.4",
    "semver": "^7.8.4"
  },
  "overrides": {
    "@opencode-ai/sdk": "$@opencode-ai/sdk",
    "@opencode-ai/plugin": {
      "zod": "^4.6.6"
    },
    "tar": "^7.5.11",
    "node-gyp": "^12.4.0",
    "esbuild": "^0.28.1",
    "toml": "^5.0.1"
  },
  "peerDependencies": {
    "@ai-sdk/provider": "^3.0.0"
  },
  "devDependencies": {
    "@ai-sdk/provider": "^3.0.19",
    "@opencode-ai/sdk": "^1.19.4",
    "@types/node": "^26.6.5",
    "@types/semver": "^7.8.0",
    "tsup": "^8.5.1",
    "typescript": "^6.0.3",
    "vitest": "^5.0.5"
  }
}
